#!/usr/bin/env python3
from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
import textwrap
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BRANCH = "refactor/direct-ubuntu-runtime"


def run(*args: str, check: bool = True, cwd: Path | None = None, env: dict[str, str] | None = None) -> subprocess.CompletedProcess[str]:
    print("+", " ".join(args), flush=True)
    merged = os.environ.copy()
    if env:
        merged.update(env)
    return subprocess.run(args, cwd=cwd or ROOT, env=merged, text=True, check=check)


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(textwrap.dedent(content).lstrip("\n"), encoding="utf-8", newline="\n")


def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    if text.count(old) != 1:
        raise SystemExit(f"expected exactly one match in {path}: {old[:120]!r}; got {text.count(old)}")
    write(path, text.replace(old, new, 1))


def replace_all(path: str, old: str, new: str, minimum: int = 1) -> None:
    text = read(path)
    count = text.count(old)
    if count < minimum:
        raise SystemExit(f"expected at least {minimum} matches in {path}: {old[:120]!r}; got {count}")
    write(path, text.replace(old, new))


def replace_between(path: str, start: str, end: str, replacement: str) -> None:
    text = read(path)
    a = text.find(start)
    b = text.find(end, a + len(start)) if a >= 0 else -1
    if a < 0 or b < 0:
        raise SystemExit(f"cannot locate replacement range in {path}: {start!r} .. {end!r}")
    write(path, text[:a] + textwrap.dedent(replacement).lstrip("\n") + text[b:])


def commit(message: str) -> None:
    run("git", "add", "-A")
    status = subprocess.run(["git", "diff", "--cached", "--quiet"], cwd=ROOT)
    if status.returncode == 0:
        print(f"no changes for commit: {message}")
        return
    run("git", "diff", "--cached", "--check")
    run("git", "commit", "-m", message)
    run("git", "push", "origin", f"HEAD:{BRANCH}")


def phase_payload_and_network_proxy() -> None:
    write(
        "src/native/root-network-proxy/Cargo.toml",
        r'''
        [package]
        name = "minis-root-network-proxy"
        version = "0.1.0"
        edition = "2021"
        license = "GPL-3.0-only"
        description = "Single-purpose root outbound proxy for Minis direct Ubuntu guests"
        publish = false

        [[bin]]
        name = "minis-root-network-proxy"
        path = "src/main.rs"

        [profile.release]
        lto = true
        codegen-units = 1
        panic = "abort"
        strip = true
        ''',
    )
    write(
        "src/native/root-network-proxy/Cargo.lock",
        r'''
        # This file is automatically @generated by Cargo.
        # It is not intended for manual editing.
        version = 3

        [[package]]
        name = "minis-root-network-proxy"
        version = "0.1.0"
        ''',
    )
    write(
        "src/native/root-network-proxy/src/main.rs",
        r'''
        use std::io::{BufReader, Read, Write};
        use std::net::{Ipv4Addr, SocketAddr, TcpListener, TcpStream, ToSocketAddrs, UdpSocket};
        use std::process::Command;
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::sync::Arc;
        use std::thread;
        use std::time::Duration;

        const DEFAULT_LISTEN: &str = "127.0.0.1:18787";
        const MAX_HEADER_BYTES: usize = 16 * 1024;
        const MAX_CONCURRENT: usize = 64;
        const FALLBACK_DNS: &[&str] = &[
            "223.5.5.5", "114.114.114.114", "119.29.29.29", "8.8.8.8", "1.1.1.1",
        ];

        #[cfg(target_os = "android")]
        unsafe extern "C" {
            fn prctl(option: i32, arg2: usize, arg3: usize, arg4: usize, arg5: usize) -> i32;
        }

        fn main() {
            #[cfg(target_os = "android")]
            unsafe {
                const PR_SET_PDEATHSIG: i32 = 1;
                const SIGTERM: usize = 15;
                let _ = prctl(PR_SET_PDEATHSIG, SIGTERM, 0, 0, 0);
            }

            let mut listen = DEFAULT_LISTEN.to_string();
            let mut args = std::env::args().skip(1);
            while let Some(arg) = args.next() {
                match arg.as_str() {
                    "--listen" => listen = args.next().unwrap_or_else(|| usage("missing --listen value")),
                    "--help" | "-h" => usage(""),
                    other => usage(&format!("unknown argument: {other}")),
                }
            }
            if listen != DEFAULT_LISTEN {
                usage("listen address is fixed to loopback 127.0.0.1:18787");
            }
            if let Err(error) = run_forever(&listen) {
                eprintln!("root-network-proxy: {error}");
                std::process::exit(1);
            }
        }

        fn usage(error: &str) -> ! {
            if !error.is_empty() {
                eprintln!("root-network-proxy: {error}");
            }
            eprintln!("usage: minis-root-network-proxy [--listen 127.0.0.1:18787]");
            std::process::exit(if error.is_empty() { 0 } else { 2 });
        }

        fn is_fake_ip(ip: Ipv4Addr) -> bool {
            let octets = ip.octets();
            octets[0] == 198 && (octets[1] == 18 || octets[1] == 19)
        }

        fn is_forbidden_target(ip: Ipv4Addr) -> bool {
            if is_fake_ip(ip) {
                return false;
            }
            ip.is_loopback() || ip.is_private() || ip.is_link_local() || ip.is_broadcast()
        }

        fn parse_target(first_line: &str) -> Result<(String, u16, bool, String), String> {
            let parts: Vec<&str> = first_line.split_whitespace().collect();
            if parts.len() < 2 {
                return Err("bad request line".into());
            }
            let method = parts[0].to_ascii_uppercase();
            let spec = parts[1];
            if method == "CONNECT" {
                let (host, port) = split_host_port(spec, 443)?;
                return Ok((host, port, true, first_line.to_string()));
            }
            if let Some(rest) = spec.strip_prefix("http://") {
                let (auth, path) = rest.split_once('/').unwrap_or((rest, ""));
                let (host, port) = split_host_port(auth, 80)?;
                let origin = format!(
                    "{method} /{path} {}",
                    parts.get(2).copied().unwrap_or("HTTP/1.1")
                );
                return Ok((host, port, false, origin));
            }
            Err("only CONNECT or absolute-form HTTP is supported".into())
        }

        fn split_host_port(spec: &str, default_port: u16) -> Result<(String, u16), String> {
            if let Some(rest) = spec.strip_prefix('[') {
                let (host, tail) = rest.split_once(']').ok_or("bad ipv6")?;
                let port = if let Some(port) = tail.strip_prefix(':') {
                    port.parse().map_err(|_| "bad port")?
                } else {
                    default_port
                };
                return Ok((host.to_string(), port));
            }
            if let Some((host, port)) = spec.rsplit_once(':') {
                if !port.is_empty() && port.chars().all(|c| c.is_ascii_digit()) {
                    return Ok((host.to_string(), port.parse().map_err(|_| "bad port")?));
                }
            }
            Ok((spec.to_string(), default_port))
        }

        fn run_forever(listen: &str) -> Result<(), String> {
            let server = TcpListener::bind(listen).map_err(|e| format!("bind {listen}: {e}"))?;
            let active = Arc::new(AtomicUsize::new(0));
            println!("READY {listen}");
            let _ = std::io::stdout().flush();
            for incoming in server.incoming() {
                let stream = match incoming {
                    Ok(stream) => stream,
                    Err(_) => continue,
                };
                if active.load(Ordering::SeqCst) >= MAX_CONCURRENT {
                    drop(stream);
                    continue;
                }
                active.fetch_add(1, Ordering::SeqCst);
                let active = Arc::clone(&active);
                thread::spawn(move || {
                    let _ = handle_client(stream);
                    active.fetch_sub(1, Ordering::SeqCst);
                });
            }
            Ok(())
        }

        fn handle_client(mut client: TcpStream) -> Result<(), String> {
            match handle_inner(&mut client) {
                Ok(()) => Ok(()),
                Err(error) => {
                    let body = error.as_bytes();
                    let _ = write!(
                        client,
                        "HTTP/1.1 502 Bad Gateway\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        body.len()
                    );
                    let _ = client.write_all(body);
                    Err(error)
                }
            }
        }

        fn handle_inner(client: &mut TcpStream) -> Result<(), String> {
            client.set_read_timeout(Some(Duration::from_secs(30))).ok();
            client.set_write_timeout(Some(Duration::from_secs(120))).ok();
            let mut reader = BufReader::new(client.try_clone().map_err(|e| e.to_string())?);
            let mut total = 0usize;
            let mut read_line_capped = |reader: &mut BufReader<TcpStream>| -> Result<String, String> {
                let mut line = String::new();
                let mut byte = [0u8; 1];
                loop {
                    match reader.read(&mut byte) {
                        Ok(0) => return Err("eof".into()),
                        Ok(_) => {
                            line.push(byte[0] as char);
                            if byte[0] == b'\n' {
                                break;
                            }
                            if total + line.len() > MAX_HEADER_BYTES {
                                return Err("header too large".into());
                            }
                        }
                        Err(error) => return Err(error.to_string()),
                    }
                }
                total += line.len();
                Ok(line)
            };

            let first = read_line_capped(&mut reader)?;
            let (host, port, is_connect, forward_line) = parse_target(first.trim_end())?;
            let mut head = Vec::new();
            if !is_connect {
                head.extend_from_slice(forward_line.as_bytes());
                head.extend_from_slice(b"\r\n");
            }
            loop {
                let line = read_line_capped(&mut reader)?;
                if !is_connect {
                    head.extend_from_slice(line.as_bytes());
                }
                if line == "\r\n" || line == "\n" || line.is_empty() {
                    break;
                }
            }
            let buffered = reader.buffer().to_vec();
            let mut peer = reader.into_inner();
            let ip = resolve_ipv4(&host)?;
            if is_forbidden_target(ip) {
                return Err(format!("blocked private/loopback target {host}({ip})"));
            }
            let mut upstream = TcpStream::connect(SocketAddr::from((ip, port)))
                .map_err(|e| format!("{host}({ip}):{port}: {e}"))?;
            if is_connect {
                peer.write_all(b"HTTP/1.1 200 Connection Established\r\n\r\n")
                    .map_err(|e| e.to_string())?;
                if !buffered.is_empty() {
                    upstream.write_all(&buffered).map_err(|e| e.to_string())?;
                }
            } else {
                upstream.write_all(&head).map_err(|e| e.to_string())?;
                if !buffered.is_empty() {
                    upstream.write_all(&buffered).map_err(|e| e.to_string())?;
                }
            }
            peer.set_read_timeout(None).ok();
            peer.set_write_timeout(None).ok();
            upstream.set_read_timeout(None).ok();
            upstream.set_write_timeout(None).ok();
            pump(peer, upstream)
        }

        fn resolve_ipv4(host: &str) -> Result<Ipv4Addr, String> {
            if let Ok(ip) = host.parse::<Ipv4Addr>() {
                return Ok(ip);
            }
            if let Ok(iter) = (host, 0).to_socket_addrs() {
                for addr in iter {
                    if let SocketAddr::V4(v4) = addr {
                        return Ok(*v4.ip());
                    }
                }
            }
            let mut last = String::new();
            for dns in discover_dns().into_iter().chain(FALLBACK_DNS.iter().map(|s| s.to_string())) {
                let Ok(server) = dns.parse::<Ipv4Addr>() else { continue };
                match dns_query_a(host, &format!("{server}:53")) {
                    Ok(ip) => return Ok(ip),
                    Err(error) => last = format!("{server}: {error}"),
                }
            }
            Err(format!("dns {host}: {last}"))
        }

        fn discover_dns() -> Vec<String> {
            let mut found = Vec::new();
            for key in [
                "net.dns1", "net.dns2", "net.dns3", "dhcp.wlan0.dns1", "dhcp.wlan0.dns2", "dhcp.eth0.dns1",
            ] {
                if let Ok(output) = Command::new("/system/bin/getprop").arg(key).output() {
                    let value = String::from_utf8_lossy(&output.stdout).trim().to_string();
                    if usable_dns(&value) && !found.contains(&value) {
                        found.push(value);
                    }
                }
            }
            if let Ok(output) = Command::new("/system/bin/dumpsys").arg("connectivity").output() {
                let text = String::from_utf8_lossy(&output.stdout);
                for line in text.lines() {
                    let lower = line.to_ascii_lowercase();
                    let Some(start) = lower.find("dnsaddresses") else { continue };
                    let rest = &line[start..];
                    let Some(open) = rest.find('[') else { continue };
                    let Some(close) = rest[open..].find(']') else { continue };
                    for token in rest[open + 1..open + close]
                        .split(|c: char| !c.is_ascii_hexdigit() && c != '.' && c != ':')
                    {
                        if usable_dns(token) && !found.iter().any(|value| value == token) {
                            found.push(token.to_string());
                        }
                    }
                }
            }
            found
        }

        fn usable_dns(value: &str) -> bool {
            if let Ok(ip) = value.parse::<Ipv4Addr>() {
                return !ip.is_unspecified() && !ip.is_loopback() && !ip.is_broadcast();
            }
            false
        }

        fn dns_query_a(host: &str, server: &str) -> Result<Ipv4Addr, String> {
            let mut query = Vec::new();
            query.extend_from_slice(&[0x12, 0x34, 0x01, 0x00, 0x00, 0x01, 0, 0, 0, 0, 0, 0]);
            for label in host.split('.') {
                if label.is_empty() || label.len() > 63 {
                    return Err("bad name".into());
                }
                query.push(label.len() as u8);
                query.extend_from_slice(label.as_bytes());
            }
            query.push(0);
            query.extend_from_slice(&[0, 1, 0, 1]);
            let socket = UdpSocket::bind("0.0.0.0:0").map_err(|e| e.to_string())?;
            socket.set_read_timeout(Some(Duration::from_secs(3))).map_err(|e| e.to_string())?;
            socket.send_to(&query, server).map_err(|e| e.to_string())?;
            let mut buf = [0u8; 512];
            let (size, _) = socket.recv_from(&mut buf).map_err(|e| e.to_string())?;
            parse_dns_a(&buf[..size])
        }

        fn parse_dns_a(msg: &[u8]) -> Result<Ipv4Addr, String> {
            if msg.len() < 12 {
                return Err("short dns".into());
            }
            let answers = u16::from_be_bytes([msg[6], msg[7]]) as usize;
            let mut index = 12usize;
            while index < msg.len() && msg[index] != 0 {
                index += 1 + msg[index] as usize;
            }
            index += 5;
            for _ in 0..answers {
                if index + 12 > msg.len() { break; }
                if msg[index] & 0xc0 == 0xc0 {
                    index += 2;
                } else {
                    while index < msg.len() && msg[index] != 0 {
                        index += 1 + msg[index] as usize;
                    }
                    index += 1;
                }
                if index + 10 > msg.len() { break; }
                let kind = u16::from_be_bytes([msg[index], msg[index + 1]]);
                let length = u16::from_be_bytes([msg[index + 8], msg[index + 9]]) as usize;
                index += 10;
                if kind == 1 && length == 4 && index + 4 <= msg.len() {
                    return Ok(Ipv4Addr::new(msg[index], msg[index + 1], msg[index + 2], msg[index + 3]));
                }
                index += length;
            }
            Err("no A".into())
        }

        fn pump(a: TcpStream, b: TcpStream) -> Result<(), String> {
            let a2 = a.try_clone().map_err(|e| e.to_string())?;
            let b2 = b.try_clone().map_err(|e| e.to_string())?;
            let handle = thread::spawn(move || copy(a2, b2));
            copy(b, a);
            let _ = handle.join();
            Ok(())
        }

        fn copy(mut reader: TcpStream, mut writer: TcpStream) {
            let mut buf = [0u8; 64 * 1024];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) | Err(_) => break,
                    Ok(size) => {
                        if writer.write_all(&buf[..size]).is_err() {
                            break;
                        }
                    }
                }
            }
            let _ = writer.shutdown(std::net::Shutdown::Write);
        }

        #[cfg(test)]
        mod tests {
            use super::*;

            #[test]
            fn connect_and_http_targets_parse() {
                let (host, port, connect, _) = parse_target("CONNECT example.com:443 HTTP/1.1").unwrap();
                assert_eq!((host, port, connect), ("example.com".to_string(), 443, true));
                let (host, port, connect, line) = parse_target("GET http://ports.ubuntu.com/ubuntu-ports/ HTTP/1.1").unwrap();
                assert_eq!((host, port, connect), ("ports.ubuntu.com".to_string(), 80, false));
                assert!(line.starts_with("GET /ubuntu-ports/ "));
            }

            #[test]
            fn lan_targets_are_blocked_but_fake_ip_is_allowed() {
                assert!(is_forbidden_target(Ipv4Addr::new(127, 0, 0, 1)));
                assert!(is_forbidden_target(Ipv4Addr::new(10, 0, 0, 1)));
                assert!(is_forbidden_target(Ipv4Addr::new(192, 168, 1, 1)));
                assert!(!is_forbidden_target(Ipv4Addr::new(198, 18, 0, 1)));
                assert!(!is_forbidden_target(Ipv4Addr::new(8, 8, 8, 8)));
            }
        }
        ''',
    )

    write(
        "scripts/build-root-network-proxy-android.sh",
        r'''
        #!/usr/bin/env bash
        set -euo pipefail

        ROOT="$(cd "$(dirname "$0")/.." && pwd)"
        DIST="${DIST:-$ROOT/dist}"
        TARGET="aarch64-linux-android"
        API_LEVEL="${ANDROID_MIN_SDK:-26}"
        NDK_VERSION="${MINIS_NDK_VERSION:-28.2.13676358}"

        case "$(uname -s)" in
          Linux) HOST_TAG="linux-x86_64"; TOOL_SUFFIX=""; CLANG_SUFFIX="" ;;
          Darwin) HOST_TAG="darwin-x86_64"; TOOL_SUFFIX=""; CLANG_SUFFIX="" ;;
          MINGW*|MSYS*) HOST_TAG="windows-x86_64"; TOOL_SUFFIX=".exe"; CLANG_SUFFIX=".cmd" ;;
          *) echo "error: unsupported host for root-network-proxy Android build" >&2; exit 2 ;;
        esac

        if [[ -n "${ANDROID_NDK_HOME:-}" ]]; then
          NDK="$ANDROID_NDK_HOME"
        elif [[ -n "${ANDROID_NDK_ROOT:-}" ]]; then
          NDK="$ANDROID_NDK_ROOT"
        elif [[ -n "${ANDROID_SDK_ROOT:-${ANDROID_HOME:-}}" ]]; then
          NDK="${ANDROID_SDK_ROOT:-${ANDROID_HOME}}/ndk/$NDK_VERSION"
        else
          echo "error: set ANDROID_SDK_ROOT or ANDROID_NDK_HOME" >&2
          exit 2
        fi
        if [[ "$HOST_TAG" == "windows-x86_64" ]]; then NDK="$(cygpath -u "$NDK")"; fi

        TOOLCHAIN="$NDK/toolchains/llvm/prebuilt/$HOST_TAG/bin"
        CLANG="$TOOLCHAIN/${TARGET}${API_LEVEL}-clang$CLANG_SUFFIX"
        READELF="$TOOLCHAIN/llvm-readelf$TOOL_SUFFIX"
        [[ -f "$CLANG" && -f "$READELF" ]] || { echo "error: Android NDK toolchain unavailable: $TOOLCHAIN" >&2; exit 2; }
        rustup target list --installed | grep -Fxq "$TARGET" || { echo "error: Rust target $TARGET is not installed" >&2; exit 2; }

        if [[ "$HOST_TAG" == "windows-x86_64" ]]; then
          export CARGO_TARGET_AARCH64_LINUX_ANDROID_LINKER="$(cygpath -w "$CLANG")"
        else
          export CARGO_TARGET_AARCH64_LINUX_ANDROID_LINKER="$CLANG"
        fi
        export RUSTFLAGS="${RUSTFLAGS:+$RUSTFLAGS }-C relocation-model=pic -C link-arg=-pie -C link-arg=-Wl,-z,max-page-size=16384 -C link-arg=-Wl,-z,common-page-size=16384"

        cargo build --locked --release --target "$TARGET" --manifest-path "$ROOT/src/native/root-network-proxy/Cargo.toml"
        BINARY="$ROOT/src/native/root-network-proxy/target/$TARGET/release/minis-root-network-proxy"
        [[ -f "$BINARY" ]] || { echo "error: root network proxy build output missing" >&2; exit 1; }

        HEADER="$($READELF -h -l -d -W "$BINARY")"
        grep -Eq 'Class:[[:space:]]+ELF64' <<<"$HEADER" || { echo "error: root network proxy is not ELF64" >&2; exit 1; }
        grep -Eq 'Machine:[[:space:]]+AArch64' <<<"$HEADER" || { echo "error: root network proxy is not AArch64" >&2; exit 1; }
        grep -Eq 'Type:[[:space:]]+DYN' <<<"$HEADER" || { echo "error: root network proxy is not PIE/ET_DYN" >&2; exit 1; }
        grep -Fq '/system/bin/linker64' <<<"$HEADER" || { echo "error: root network proxy is not linked for Android" >&2; exit 1; }
        if awk '$1 == "LOAD" && $NF != "0x4000" { bad=1 } END { exit bad ? 0 : 1 }' <<<"$HEADER"; then
          echo "error: root network proxy LOAD segments are not all 16 KB aligned" >&2
          exit 1
        fi
        grep -Fq 'libc.so' <<<"$HEADER" || { echo "error: root network proxy has no Android libc dependency" >&2; exit 1; }
        if grep -Eq 'ld-linux|libglibc' <<<"$HEADER"; then echo "error: root network proxy unexpectedly depends on glibc" >&2; exit 1; fi

        mkdir -p "$DIST"
        install -m 0755 "$BINARY" "$DIST/minis-root-network-proxy-arm64-v8a"
        sha256sum "$DIST/minis-root-network-proxy-arm64-v8a" > "$DIST/minis-root-network-proxy-arm64-v8a.sha256"
        echo "==> $DIST/minis-root-network-proxy-arm64-v8a"
        ''',
    )

    write(
        "scripts/verify-root-network-proxy.sh",
        r'''
        #!/usr/bin/env bash
        set -euo pipefail
        INPUT="${1:-}"
        [[ -n "$INPUT" && -e "$INPUT" ]] || { echo "usage: $0 path/to/dist-or.apk" >&2; exit 2; }

        python3 - "$INPUT" <<'PY'
        import hashlib
        import pathlib
        import re
        import sys
        import zipfile

        source = pathlib.Path(sys.argv[1])
        if source.is_dir():
            binary_path = source / "minis-root-network-proxy-arm64-v8a"
            checksum_path = source / "minis-root-network-proxy-arm64-v8a.sha256"
            if not binary_path.is_file() or not checksum_path.is_file():
                raise SystemExit("root network proxy payload is incomplete")
            binary = binary_path.read_bytes()
            expected = checksum_path.read_text(encoding="utf-8").split()[0].lower()
            if not re.fullmatch(r"[0-9a-f]{64}", expected):
                raise SystemExit("root network proxy checksum file is invalid")
            if hashlib.sha256(binary).hexdigest() != expected:
                raise SystemExit("root network proxy SHA-256 mismatch")
        else:
            with zipfile.ZipFile(source) as archive:
                path = "lib/arm64-v8a/libminisnetproxy.so"
                try:
                    binary = archive.read(path)
                except KeyError:
                    raise SystemExit(f"root network proxy is missing from APK: {path}") from None
                if "lib/arm64-v8a/libminisd.so" in archive.namelist():
                    raise SystemExit("obsolete libminisd.so is still packaged")

        if not binary.startswith(b"\x7fELF") or len(binary) < 20:
            raise SystemExit("root network proxy is not an ELF binary")
        if binary[4] != 2 or binary[5] != 1:
            raise SystemExit("root network proxy is not little-endian ELF64")
        if int.from_bytes(binary[16:18], "little") != 3:
            raise SystemExit("root network proxy is not PIE/ET_DYN")
        if int.from_bytes(binary[18:20], "little") != 183:
            raise SystemExit("root network proxy is not AArch64")
        print(f"root network proxy verified: sha256={hashlib.sha256(binary).hexdigest()}")
        PY
        ''',
    )

    write(
        "src/android/app/src/main/java/com/openminis/app/runtime/ubuntu/RootNetworkProxy.kt",
        r'''
        package com.openminis.app.runtime.ubuntu

        import android.content.Context
        import android.util.Log
        import kotlinx.coroutines.delay
        import kotlinx.coroutines.sync.Mutex
        import kotlinx.coroutines.sync.withLock
        import java.io.File
        import java.net.InetSocketAddress
        import java.net.Socket

        /**
         * Single-purpose Root outbound proxy for direct Ubuntu guests.
         *
         * Android/VPN BPF policy can block App-UID guest sockets while Root has
         * working egress. This loopback-only helper preserves that compatibility
         * without restoring a generic Root daemon, RPC protocol, or command API.
         */
        internal object RootNetworkProxy {
            const val PROXY_LISTEN = "127.0.0.1:18787"
            const val PROXY_URI = "http://127.0.0.1:18787"
            private const val TAG = "RootNetworkProxy"
            private const val BINARY = "libminisnetproxy.so"
            private val lock = Mutex()

            data class Status(val ready: Boolean, val detail: String? = null)

            @Volatile
            private var process: Process? = null

            suspend fun ensureReady(context: Context): Status = lock.withLock {
                if (listenerReady()) return@withLock Status(true)
                process?.let { stale ->
                    runCatching { stale.destroyForcibly() }
                    process = null
                }

                val su = DirectRootRunner.findSu()
                    ?: return@withLock Status(false, "Root launcher is unavailable for outbound network proxy")
                val binary = File(context.applicationInfo.nativeLibraryDir, BINARY)
                if (!binary.isFile) {
                    return@withLock Status(false, "packaged Root network proxy is missing: ${binary.absolutePath}")
                }

                val command = "exec ${DirectRootRunner.shellQuote(binary.absolutePath)} --listen ${DirectRootRunner.shellQuote(PROXY_LISTEN)}"
                val child = try {
                    ProcessBuilder(su, "-c", command)
                        .redirectErrorStream(true)
                        .start()
                } catch (error: Throwable) {
                    return@withLock Status(false, "cannot start Root network proxy: ${error.message}")
                }
                process = child
                Thread({
                    runCatching {
                        child.inputStream.bufferedReader().useLines { lines ->
                            lines.forEach { Log.d(TAG, it) }
                        }
                    }
                }, "minis-root-network-proxy-log").apply {
                    isDaemon = true
                    start()
                }

                repeat(80) {
                    if (!child.isAlive) {
                        process = null
                        return@withLock Status(false, "Root network proxy exited before becoming ready")
                    }
                    if (listenerReady()) return@withLock Status(true)
                    delay(25)
                }
                runCatching { child.destroyForcibly() }
                process = null
                Status(false, "Root network proxy did not bind $PROXY_LISTEN")
            }

            fun proxyEnv(): Map<String, String> = linkedMapOf(
                "http_proxy" to PROXY_URI,
                "https_proxy" to PROXY_URI,
                "HTTP_PROXY" to PROXY_URI,
                "HTTPS_PROXY" to PROXY_URI,
                "all_proxy" to PROXY_URI,
                "ALL_PROXY" to PROXY_URI,
                "no_proxy" to "localhost,127.0.0.1,::1",
                "NO_PROXY" to "localhost,127.0.0.1,::1",
            )

            private fun listenerReady(): Boolean = try {
                Socket().use { socket ->
                    socket.connect(InetSocketAddress("127.0.0.1", 18787), 150)
                }
                true
            } catch (_: Throwable) {
                false
            }
        }
        ''',
    )

    kernel = read("src/android/app/src/main/java/com/openminis/app/runtime/ubuntu/UbuntuKernel.kt")
    marker = '''        val provisioned = UbuntuProvisioner.ensureProvisioned(ctx)\n'''
