    network = '''        val network = RootNetworkProxy.ensureReady(ctx)\n        if (!network.ready) {\n            return@withLock Status(false, error = network.detail ?: "Root outbound network proxy unavailable")\n        }\n\n'''
    kernel = kernel.replace(marker, network + marker, 1)
    kernel = kernel.replace("env.putAll(RuntimePathRegistry.systemProxyEnv(ctx))", "env.putAll(RootNetworkProxy.proxyEnv())", 1)
    write("src/android/app/src/main/java/com/openminis/app/runtime/ubuntu/UbuntuKernel.kt", kernel)

    provisioner = read("src/android/app/src/main/java/com/openminis/app/runtime/ubuntu/UbuntuProvisioner.kt")
