def acceptance_and_cleanup() -> None:
    # Remove all one-off refactor scaffolding in the working tree before testing,
    # so the tested tree is exactly the tree committed by the final cleanup commit.
    for path in [
        ".github/workflows/tmp-direct-runtime-inventory.yml",
        ".github/scripts/phase1_direct_runtime_patch.py",
        ".github/scripts/phase2a_direct_runtime_cleanup.py",
        ".github/scripts/phase2b_direct_guest_bridge.py",
        ".github/scripts/phase2c_wire_provisioner.py",
        ".github/scripts/phase3_direct_runtime_cleanup.py",
    ]:
        target = ROOT / path
        if target.is_file(): target.unlink()

    run("git", "diff", "--check")
    run("python3", "scripts/test_build_cleanup_guard.py")
    run("python3", "scripts/check_build_cleanup.py")
    run("bash", "scripts/test-build-ubuntu-rootfs-verification.sh")
    run("bash", "scripts/test-runtime-payload-verification.sh")
    run("bash", "scripts/check-runtime-package-boundary.sh")
    run("cargo", "fmt", "--manifest-path", "src/native/root-network-proxy/Cargo.toml", "--all", "--", "--check")
    run("cargo", "clippy", "--locked", "--manifest-path", "src/native/root-network-proxy/Cargo.toml", "--all-targets", "--", "-D", "warnings")
    run("cargo", "test", "--locked", "--manifest-path", "src/native/root-network-proxy/Cargo.toml")

    # Full Android acceptance requires the same native prerequisites as canonical CI.
    sdkmanager = Path(os.environ["ANDROID_HOME"]) / "cmdline-tools/latest/bin/sdkmanager"
    run(str(sdkmanager), "ndk;28.2.13676358")
    ndk = Path(os.environ["ANDROID_HOME"]) / "ndk/28.2.13676358"
    os.environ["ANDROID_NDK_HOME"] = str(ndk)
    run("rustup", "target", "add", "aarch64-linux-android")
    run("bash", "scripts/build-root-network-proxy-android.sh")
    run("bash", "scripts/verify-root-network-proxy.sh", "dist")
    run("bash", "scripts/build-runtime-payload.sh")

    # rclone AAR required by every Android compile in this repository.
    gopath = subprocess.check_output(["go", "env", "GOPATH"], text=True).strip()
    env = {"PATH": f"{gopath}/bin:{os.environ['PATH']}"}
    run("go", "install", "golang.org/x/mobile/cmd/gomobile@f98cc9b", env=env)
    run("gomobile", "init", env=env)
    run("bash", "deps/build_rclone_android.sh", env=env)
    libs = ROOT / "src/android/app/libs"
    libs.mkdir(parents=True, exist_ok=True)
    shutil.copy2(ROOT / "deps/build/rclone/rclone.aar", libs / "rclone.aar")

    android = ROOT / "src/android"
    gradle_env = {"MINIS_REQUIRE_RUNTIME_PAYLOAD": "1"}
    run("./gradlew", ":app:compileDebugKotlin", "--max-workers=4", "--stacktrace", cwd=android, env=gradle_env)
    run("./gradlew", ":app:testDebugUnitTest", "--max-workers=4", "--stacktrace", cwd=android, env=gradle_env)
    run("./gradlew", ":app:assembleDebug", "--max-workers=4", "--stacktrace", cwd=android, env=gradle_env)
    apk = "src/android/app/build/outputs/apk/debug/app-debug.apk"
    run("bash", "scripts/verify-runtime-payload.sh", apk)
    run("bash", "scripts/verify-root-network-proxy.sh", apk)
    run("bash", "scripts/verify-android-16k.sh", apk)

    grep = subprocess.run(
        ["git", "grep", "-n", "-E", "minisd|Minisd|libminisd\\.so|minisd-arm64-v8a|runtime\\.minisd|minisd\\.sock"],
        cwd=ROOT, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
    )
    print("=== final minisd grep ===")
    print(grep.stdout)
    forbidden = []
    for line in grep.stdout.splitlines():
        path = line.split(":", 1)[0]
        if path.startswith(("src/android/", "scripts/", ".github/workflows/")):
            forbidden.append(line)
    if forbidden:
        print("Forbidden active minisd references remain:", *forbidden, sep="\n", file=sys.stderr)
        raise SystemExit(1)

    commit("chore: remove direct-runtime refactor scaffolding")


def main() -> None:
    os.chdir(ROOT)
    run("git", "config", "user.name", "github-actions[bot]")
    run("git", "config", "user.email", "41898282+github-actions[bot]@users.noreply.github.com")
    branch = subprocess.check_output(["git", "branch", "--show-current"], cwd=ROOT, text=True).strip()
    if branch != BRANCH:
        raise SystemExit(f"refusing to run on {branch!r}; expected {BRANCH}")
    phase_payload_and_network_proxy()
    phase_remove_minisd()
    phase_ci()
    phase_guards()
    phase_docs()
    acceptance_and_cleanup()


if __name__ == "__main__":
    main()
